toolArgs.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_508fc87f48054f59a76774eba2f27475.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < _stepNames.Length; i++)
    {
        var stepIndex = i;
        var cssClass = GetStepClass(stepIndex);
        <div class="step @cssClass" @onclick="() => GoToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < _currentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@_stepNames[stepIndex]</div>
        </div>
        @if (i < _stepNames.Length - 1)
        {
            <div class="step-connector"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger mt-3">@_errorMessage</div>
}

@* Step Content *@
<div class="step-content mt-4">
    @switch (_currentStep)
    {
        case 0:
            @RenderPersonalInfo()
            break;
        case 1:
            @RenderWorkHistory()
            break;
        case 2:
            @RenderReferences()
            break;
        case 3:
            @RenderCoverLetter()
            break;
        case 4:
            @RenderReviewAndSubmit()
            break;
    }
</div>

@code {
    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int _currentStep;
    private string _errorMessage = string.Empty;
    private bool _isSubmitting;
    private int? _submittedApplicationId;

    // Step 1: Personal Info
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2: Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string _coverLetter = string.Empty;
    private const int MaxCoverLetterLength = 2000;

    private string GetStepClass(int step)
    {
        if (step == _currentStep) return "active";
        if (step < _currentStep) return "completed";
        return "dimmed";
    }

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _currentStep = step;
            _errorMessage = string.Empty;
        }
    }

    private async Task NextStep()
    {
        _errorMessage = string.Empty;

        switch (_currentStep)
        {
            case 0:
                if (!ValidatePersonalInfo()) return;
                var emailValid = await ApplicationService.ValidateEmailAsync(_email);
                if (!emailValid)
                {
                    _errorMessage = "Please enter a valid email address.";
                    return;
                }
                break;
            case 1:
                if (!ValidateWorkHistory()) return;
                break;
            case 2:
                if (!ValidateReferences()) return;
                break;
            case 3:
                break;
        }

        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
            _errorMessage = string.Empty;
        }
    }

    private bool ValidatePersonalInfo()
    {
        if (string.IsNullOrWhiteSpace(_fullName))
        {
            _errorMessage = "Full name is required.";
            return false;
        }
        if (string.IsNullOrWhiteSpace(_email))
        {
            _errorMessage = "Email is required.";
            return false;
        }
        if (string.IsNullOrWhiteSpace(_phone))
        {
            _errorMessage = "Phone number is required.";
            return false;
        }
        if (string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Address is required.";
            return false;
        }
        return true;
    }

    private bool ValidateWorkHistory()
    {
        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _errorMessage = "Each work entry must have a company name and job title.";
                return false;
            }
            if (entry.StartDate == default)
            {
                _errorMessage = "Each work entry must have a start date.";
                return false;
            }
        }
        return true;
    }

    private bool ValidateReferences()
    {
        foreach (var reference in _references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Email))
            {
                _errorMessage = "Each reference must have a name and email.";
                return false;
            }
        }
        return true;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = string.Empty;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workEntries = _workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList();
            var work = new WorkHistory(workEntries);
            var references = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, work, references, _coverLetter);
            _submittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private void AddWorkEntry()
    {
        _workEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(WorkEntryModel entry)
    {
        if (_workEntries.Count > 1)
        {
            _workEntries.Remove(entry);
        }
    }

    private void AddReference()
    {
        if (_references.Count < 3)
        {
            _references.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(ReferenceModel reference)
    {
        if (_references.Count > 2)
        {
            _references.Remove(reference);
        }
    }

    // View models for mutable form state
    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }

    // Render fragments
    private RenderFragment RenderPersonalInfo() => __builder =>
    {
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name *</label>
            <input type="text" class="form-control" @bind="_fullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" @bind="_phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address *</label>
            <input type="text" class="form-control" @bind="_address" />
        </div>
        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderWorkHistory() => __builder =>
    {
        <h3>Work History</h3>
        @for (int i = 0; i < _workEntries.Count; i++)
        {
            var entry = _workEntries[i];
            var entryIndex = i;
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5>Position @(entryIndex + 1)</h5>
                    @if (_workEntries.Count > 1)
                    {
                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveWorkEntry(entry)">Remove</button>
                    }
                </div>
                <div class="mb-2">
                    <label class="form-label">Company *</label>
                    <input type="text" class="form-control" @bind="entry.Company" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Job Title *</label>
                    <input type="text" class="form-control" @bind="entry.Title" />
                </div>
                <div class="row mb-2">
                    <div class="col-md-4">
                        <label class="form-label">Start Date *</label>
                        <input type="date" class="form-control" @bind="entry.StartDate" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                    </div>
                    <div class="col-md-4 d-flex align-items-end">
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" @bind="entry.IsCurrent" id="@($"current-{entryIndex}")" />
                            <label class="form-check-label" for="@($"current-{entryIndex}")">Currently working here</label>
                        </div>
                    </div>
                </div>
                <div class="mb-2">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="3" @bind="entry.Description"></textarea>
                </div>
            </div>
        }
        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderReferences() => __builder =>
    {
        <h3>References</h3>
        @for (int i = 0; i < _references.Count; i++)
        {
            var reference = _references[i];
            var refIndex = i;
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5>Reference @(refIndex + 1)</h5>
                    @if (_references.Count > 2)
                    {
                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveReference(reference)">Remove</button>
                    }
                </div>
                <div class="mb-2">
                    <label class="form-label">Name *</label>
                    <input type="text" class="form-control" @bind="reference.Name" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Relationship</label>
                    <input type="text" class="form-control" @bind="reference.Relationship" />
                </div>
                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Email *</label>
                        <input type="email" class="form-control" @bind="reference.Email" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Phone</label>
                        <input type="tel" class="form-control" @bind="reference.Phone" />
                    </div>
                </div>
            </div>
        }
        @if (_references.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderCoverLetter() => __builder =>
    {
        <h3>Cover Letter</h3>
        <div class="mb-3">
            <textarea class="form-control" rows="10" @bind="_coverLetter" maxlength="@MaxCoverLetterLength"></textarea>
            <div class="form-text text-end">@_coverLetter.Length / @MaxCoverLetterLength characters</div>
        </div>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderReviewAndSubmit() => __builder =>
    {
        @if (_submittedApplicationId.HasValue)
        {
            <div class="alert alert-success">
                <h4>Application Submitted Successfully!</h4>
                <p>Your application ID is: <strong>@_submittedApplicationId.Value</strong></p>
                <p>Thank you for applying. We will be in touch soon.</p>
            </div>
        }
        else
        {
            <h3>Review & Submit</h3>

            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Personal Information</h5>
                    <a href="javascript:void(0)" @onclick="() => GoToStep(0)">Edit</a>
                </div>
                <p><strong>Name:</strong> @_fullName</p>
                <p><strong>Email:</strong> @_email</p>
                <p><strong>Phone:</strong> @_phone</p>
                <p><strong>Address:</strong> @_address</p>
            </div>

            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Work History</h5>
                    <a href="javascript:void(0)" @onclick="() => GoToStep(1)">Edit</a>
                </div>
                @foreach (var entry in _workEntries)
                {
                    <div class="mb-2 ps-3 border-start">
                        <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                        <p class="mb-1 text-muted">
                            @entry.StartDate.ToString("MMM yyyy") &mdash;
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </p>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>References</h5>
                    <a href="javascript:void(0)" @onclick="() => GoToStep(2)">Edit</a>
                </div>
                @foreach (var reference in _references)
                {
                    <div class="mb-2 ps-3 border-start">
                        <p class="mb-1"><strong>@reference.Name</strong> (@reference.Relationship)</p>
                        <p class="mb-0 text-muted">@reference.Email @(!string.IsNullOrWhiteSpace(reference.Phone) ? $"| {reference.Phone}" : "")</p>
                    </div>
                }
            </div>

            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Cover Letter</h5>
                    <a href="javascript:void(0)" @onclick="() => GoToStep(3)">Edit</a>
                </div>
                <p style="white-space: pre-wrap;">@_coverLetter</p>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @(_isSubmitting ? "Submitting..." : "Submit Application")
                </button>
            </div>
        }
    };
}

